"""Twenty explicit reviews; residual remissions and special laws remain qualified."""
import json,sys
from pathlib import Path
rows={}
def add(n,text,points,warning,case,variation,qa,term,meaning):
 rows['art-'+str(n)]=dict(simples=text,pontos=points,atencao=[warning],exemplo=case+' Variação: '+variation,prova=qa,termos=[dict(termo=term,significado=meaning)],remissoes=['https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm'])
add(137,'Participar de rixa tem detenção de quinze dias a dois meses ou multa; atuação para separar contendores é ressalvada. Morte ou lesão grave tem pena qualificada pela participação, sem apagar outros enquadramentos individuais.', ['Resultado qualificado: seis meses a dois anos.', 'Separar não equivale a participar da luta.'], 'Não tratar agressão unilateral ou qualquer discussão verbal como rixa. Imputação de resultado, autoria específica e relação com participação exigem análise; não dispensar prova por estar no local.', 'Pessoa intervém apenas para separar a luta: a ressalva impede presumir participação típica.', 'Se passa a integrar a luta, a conduta muda; ainda provar requisitos e eventual resultado qualificado.', ['Quem apenas separa integra necessariamente o crime? Não.', 'Toda discussão verbal configura rixa? Não; examinar o tipo.'],'Rixa','Participação na luta nas condições típicas, distinta de separar.')
add(138,'Calúnia imputa falsamente fato definido como crime; não é apenas xingamento. Divulgar sabendo falsa a imputação é hipótese própria; calúnia contra mortos é punível. Exceção da verdade tem restrições expressas.', ['Pena: seis meses a dois anos e multa.', '§1º exige saber falsa; §3º lista exceções à prova da verdade.'], 'Não usar verdadeira informação como calúnia automática nem toda crítica como imputação criminosa. Exceção da verdade não é admitida universalmente, e crimes contra honra têm regime próprio de ação.', 'Alguém atribui falsamente um furto concreto: examinar imputação de fato criminoso e elementos do tipo.', 'Se apenas dirige ofensa à dignidade sem fato, avaliar injúria, não calúnia por rótulo.', ['Toda ofensa é calúnia? Não; exige fato definido como crime.', 'Prova da verdade cabe sem exceções? Não; ler §3º.'],'Imputação criminosa','Atribuição de fato criminoso concreto, distinta de ofensa genérica.')
add(139,'Difamação imputa fato ofensivo à reputação; não exige que o fato seja definido como crime. A verdade não exclui automaticamente todo caso: a exceção textual exige funcionário público e ligação com função.', ['Pena: três meses a um ano e multa.', 'Exceção: funcionário público E ofensa relativa às funções.'], 'Distinguir fato e juízo ofensivo, contexto e direito de crítica. Não ensinar que divulgar qualquer fato verdadeiro sempre é impune nem presumir crime por crítica legítima.', 'Fato ofensivo não criminoso é divulgado sobre pessoa: examinar difamação, não calúnia automaticamente.', 'Se o ofendido é funcionário e a ofensa se refere à função, muda a hipótese da exceção, sem dispensar os demais elementos.', ['O fato precisa ser crime? Não.', 'Toda verdade afasta automaticamente difamação? Não; a exceção tem recorte.'],'Reputação','Honra objetiva relacionada à consideração social.')
add(140,'Injúria ofende dignidade/decoro. O §3º atual abrange religião ou condição de pessoa idosa/com deficiência; injúria racial passou à Lei7.716, art.2º-A, após Lei14.532 publicada e vigente em11/1/2023.', ['Caput: um a seis meses OU multa; real: três meses a um ano E multa, além da violência.', '§3º: um a três anos E multa no recorte atual.', '§1º admite deixar de aplicar pena nas hipóteses de provocação/retorsão imediata.'], 'Não copiar raça/cor/etnia/origem da redação histórica do §3º como enquadramento atual de injúria racial. Não confundir perdão judicial facultativo com direito de agredir ou imunidade geral; lei no tempo exige integração à norma especial, sem revisar novamente todo percurso Racismo.', 'Ofensa racial após a alteração de2023 é classificada mecanicamente no antigo §3º do CP.', 'Se a ofensa utiliza religião ou condição indicada no §3º atual, examinar este recorte e seu regime, sem equiparar automaticamente todas as hipóteses.', ['Raça permanece no §3º atual? Não; integrar Lei7.716 art.2º-A.', 'Retorsão imediata autoriza qualquer violência? Não; observar a hipótese legal.'],'Honra subjetiva','Dignidade/decoro pessoais, com modalidades e disciplina especial.')
add(141,'Crimes de honra têm aumentos por destinatário/contexto, recompensa, redes sociais e razões da condição do sexo feminino. Frações não se somam automaticamente por qualquer rótulo.', ['Regra: um terço nas hipóteses dos incisos.', 'Paga/promessa: dobro; redes sociais: triplo.', 'Lei14.994 vigente10/10/2024: dobro na hipótese do §3º.', 'IncisoIV ressalva art.140§3º; função exige relação pertinente.'], 'Não usar aplicativo/celular como prova automática de qualquer divulgação em rede social nem duplicar a mesma condição já elementar. Conferir vigência da parte promulgada depois de veto e irretroatividade gravosa; não certificar todo concurso de majorantes neste bloco.', 'A condição etária já integra a injúria do §3º e a questão aplica também incisoIV pelo mesmo dado, ignorando ressalva.', 'Se a hipótese não tem essa elementar, examinar o inciso com seus requisitos e regras de dosimetria, sem conclusão por etiqueta.', ['IncisoIV ignora §3º do140? Não; há exceção.', 'Toda hipótese tem a mesma fração? Não; um terço, dobro e triplo são distintos.'],'Majorantes da honra','Aumentos condicionados ao contexto e sem duplicação automática.')
add(142,'As hipóteses textuais de exclusão abrangem injúria/difamação em discussão da causa, crítica pertinente ou dever funcional. Não mencionam calúnia como licença irrestrita; publicidade nos incisos I/III tem ressalva.', ['Crítica: ressalva de intenção inequívoca de injuriar/difamar.', 'Juízo: discussão da causa, parte/procurador.', 'Publicidade pode gerar responsabilidade no recorte do parágrafo.'], 'Não transformar atuação profissional em autorização de qualquer ofensa alheia à causa ou calúnia. Garantias específicas e contexto exigem verificação; a lista não é licença universal.', 'Advogado atribui falsamente crime e invoca o art.142 como imunidade universal de calúnia.', 'Se a fala é pertinente à discussão e se enquadra nas hipóteses de injúria/difamação, examinar limites e publicidade, sem presumir toda ofensa protegida.', ['O artigo exclui universalmente calúnia? Não.', 'Crítica com intenção inequívoca de ofender é sempre protegida peloII? Não; há ressalva.'],'Exclusão delimitada','Hipótese com objeto e contexto próprios, não autorização irrestrita.')
add(143,'Retratação cabal de calúnia/difamação antes da sentença pode isentar pena. Se foi por comunicação, o ofendido pode desejar os mesmos meios. Injúria não integra automaticamente esse recorte.', ['Cabal E antes da sentença.', 'Mesmo meio se o ofendido assim desejar.'], 'Não tratar desculpa vaga, negação parcial ou retratação tardia como cumprimento automático. Não confundir com perdão do ofendido ou direito de resposta de regime próprio.', 'Antes da sentença, o querelado se retrata integralmente de calúnia difundida por meio de comunicação e o ofendido deseja o mesmo meio.', 'Se apenas reafirma a acusação com pedido genérico de desculpas, reavaliar se houve retratação cabal, sem presumir o benefício.', ['A regra inclui qualquer injúria? Não; calúnia/difamação.', 'Basta retratação parcial por etiqueta? Não; exige cabal.'],'Retratação cabal','Retirada integral da imputação no momento e forma pertinentes.')
add(144,'Referências ambíguas podem motivar pedido judicial de explicações. O procedimento não transforma automaticamente silêncio em condenação: a ofensa e seus elementos dependem de análise com garantias.', ['Faculdade de pedir explicações.', 'Resposta ou ausência exige exame do caso, não culpa presumida.'], 'A frase responde pela ofensa não elimina presunção de inocência ou direito ao silêncio. Pedido não substitui queixa nem se presume suspensão/reinício do prazo decadencial só por sua apresentação.', 'O interpelado não responde e a questão declara condenação automática sem provar crime.', 'Resposta esclarecedora pode mudar a compreensão; ainda identificar elementos e via adequada, não condenar por ausência de explicação satisfatória sozinha.', ['Silêncio sozinho prova condenação? Não.', 'O pedido é sempre a própria ação penal? Não; distinguir procedimento e iniciativa.'],'Interpelação','Pedido de esclarecimento, sem dispensar prova e garantias.')
add(145,'Queixa é a regra textual no capítulo, com exceções para violência com lesão, requisição e representação. A disciplina da injúria racial posterior a2023 é especial, não se decide pela redação histórica do CP.', ['IncisoI do141: requisição; incisoII e140§3º: representação no texto.', 'Não confundir queixa, denúncia e representação.'], 'Não declarar exclusividade universal do MP ou da queixa em ofensa funcional por leitura isolada: legitimação concorrente e seu alcance exigem jurisprudência específica, não certificada integralmente aqui. Integrar Lei14.532 e exceções especiais.', 'A questão atribui a todo crime de honra apenas uma mesma forma de iniciativa, sem identificar o tipo e contexto.', 'Em ofensa funcional ou injúria racial, conferir regime integrado e legitimidade antes de usar resposta universal.', ['Há só uma forma de iniciativa para todo capítulo? Não.', 'Pode decidir injúria racial atual apenas pelo §3º antigo? Não; verificar lei especial.'],'Regime da ação','Titularidade e condição variam por hipótese, com integração necessária.')
add(146,'Constranger por violência/grave ameaça ou redução da resistência a não fazer o permitido ou fazer o não mandado tem hipótese própria. Mais de três pessoas ou armas têm regra agravada; exceções médicas/suicídio são delimitadas.', ['Três meses a um ano OU multa; §1º cumulativas E dobro.', 'Mais de três não é exatamente três.', 'Intervenção sem consentimento: perigo de vida IMINENTE, não conveniência geral.'], 'Não legitimar qualquer intervenção médica ou coação pelo simples nome de tratamento. Distinguir tipos especiais, elementos e garantias; penas da violência possuem previsão cumulativa própria.', 'Exatamente três pessoas atuam sem arma: esse número sozinho não preenche mais de três do §1º.', 'Se há arma, a outra hipótese do §1º precisa ser examinada, sem exigir também quatro pessoas.', ['Exatamente três basta por número? Não.', 'Toda intervenção sem consentimento está excluída? Não; observar perigo iminente de vida.'],'Constrangimento ilegal','Restrição da liberdade por meios e finalidade previstos.')
add('146-a','Bullying exige intimidação intencional, sistemática e repetitiva nos meios legais. Lei14.811, vigente15/1/2024, prevê multa na forma comum e reclusão2 a4 anos e multa na virtual, subsidiariamente a crime mais grave.', ['Caput e parágrafo têm penas diferentes.', 'Ambiente digital não dispensa repetição/intencionalidade.', 'Subsidiariedade nas duas hipóteses.'], 'Não transformar ofensa isolada em bullying automaticamente nem todo conflito em crime por opinião subjetiva. Outros tipos podem incidir; alteração penal gravosa não retroage.', 'Uma única mensagem ofensiva é chamada automaticamente de bullying por estar em rede social.', 'Com intimidação sistemática e repetitiva comprovada em ambiente digital, examinar parágrafo e subsidiariedade, sem dispensar os demais elementos.', ['Digital dispensa repetição? Não.', 'Forma comum e virtual têm só multa? Não; a virtual tem reclusão e multa.'],'Intimidação sistemática','Conduta repetitiva e intencional, distinta de qualquer episódio isolado.')
add(147,'Ameaça exige mal injusto e grave comunicado pelos meios previstos. Lei14.994, vigente10/10/2024, prevê dobro na hipótese contra mulher por razões do sexo feminino e exclui essa hipótese da exigência de representação.', ['Caput: um a seis meses OU multa.', '§2º: representação EXCETO hipótese§1º.', 'Ser mulher, sozinho, não prova razões legais.'], 'Não ensinar representação obrigatória para toda ameaça nem aplicar dobro a qualquer vítima mulher sem elementos. Não confundir anúncio de exercício legítimo de direito com mal injusto; lei penal no tempo importa.', 'Ameaça preenchida por razões legais contra mulher sob regime atual é tratada como dependente sempre de representação.', 'Em hipótese fora do §1º, examinar a regra geral condicionada; fato anterior exige análise temporal própria.', ['Toda ameaça exige representação atual? Não; há exceção.', 'Qualquer vítima mulher determina dobro? Não; exige razões legais.'],'Ameaça e ação','Mal injusto/grave e regime de iniciativa com exceção atual.')
add('147-a','Perseguição exige reiteração e afeta integridade, locomoção ou esfera de liberdade/privacidade. Pena6 meses a2 anos e multa; majorantes próprias e representação. A remissão a121§2º-A é residual após feminicídio autônomo.', ['Aumento METADE: hipóteses pessoais, concurso2 ou mais OU arma.', 'Representação no§3º, não copiar exceção da ameaça do147.', 'Integrar razões da condição do sexo feminino ao121-A atual.'], 'Não reativar §2º-A revogado nem declarar revogada toda perseguição por essa remissão. Um ato isolado não prova reiteradamente, ainda que outro crime possa existir. Não presumir perseguição só por desconforto sem elementos.', 'Um contato isolado é usado para afirmar reiteração sem outros atos comprovados.', 'Com perseguição repetida e elementos legais, examinar tipo e majorantes; ameaça concomitante tem regime próprio, não troca automática de ação.', ['Um episódio sozinho prova reiteração? Não.', 'A remissão residual revoga todo147-A? Não; exige integração.'],'Reiteração persecutória','Repetição de condutas nas hipóteses de afetação da liberdade.')
add('147-b','Violência psicológica contra mulher exige dano emocional e meios/finalidades descritos, subsidiariamente a crime mais grave. Lei15.123, vigente25/4/2025, aumenta metade quando IA ou recurso tecnológico altera imagem/som da vítima.', ['Caput:6 meses a2 anos E multa.', 'Aumento não é por qualquer uso de celular: alteração de imagem/som é requisito.', 'Dano e elementos devem ser demonstrados.'], 'Não diagnosticar crime por qualquer desentendimento ou presumir dano emocional apenas pelo rótulo. Não ampliar majorante a toda tecnologia sem alteração indicada; mudança gravosa não retroage.', 'Recurso de IA altera voz/imagem da vítima em conduta com dano emocional e elementos legais demonstrados.', 'Se houve mensagem comum sem alteração de imagem/som, não aplicar automaticamente a nova majorante, embora o caput exija análise própria.', ['Qualquer tecnologia basta à majorante? Não.', 'Dispensa elementos de dano/conduta? Não; provar o tipo.'],'Dano emocional','Resultado e afetação previstos, distintos de rótulo genérico de conflito.')
add('147-c','A ameaça no contexto/finalidade legais do combate ao crime organizado tem reclusão1 a3 anos após Lei15.358, vigente25/3/2026. O tipo exige contexto ou finalidade prevista, não apenas pronunciar nome de facção.', ['Mal injusto E grave.', 'Contexto da atuação OU consecução das condutas legais.'], 'Não importar automaticamente penas e condição de ação de todo147 nem ampliar por analogia a qualquer conflito. Provar elementos e lei no tempo; controle constitucional não foi certificado integralmente.', 'Agente usa nome de facção, mas contexto/finalidade legais não estão demonstrados.', 'Com elementos típicos e vínculo contextual provados, examinar norma especial e garantias, sem aplicar mudança gravosa a fato anterior.', ['Nome de facção sozinho resolve? Não.', 'Pena nova retroage prejudicialmente? Não.'],'Ameaça contextual','Hipótese especial dependente do contexto/finalidade legal.')
add(148,'Sequestro/cárcere priva liberdade com pena1 a3, qualificações2 a5 ou2 a8 e hipótese especial de2026. Duração superior a quinze dias não é requisito de todo caput; é qualificadora indicada.', ['§1º: parentesco/idade, internação, MAIS15 dias, menor18 ou fim libidinoso.', '§2º: grave sofrimento decorrente de maus-tratos/natureza da detenção.', '§3º:12 a20, Lei15.358 vigente25/3/2026, integrante E contexto/finalidade.'], 'Não exigir quinze dias para todo crime nem confundir com extorsão mediante sequestro. Idade e finalidade têm recortes; grupo sozinho não prova §3º, e mudanças gravosas não retroagem.', 'Privação dura exatamente quinze dias: não satisfaz mais de quinze apenas pela duração, mas o caput/outros elementos seguem relevantes.', 'Se dura dezesseis, a hipótese temporal muda, sem dispensar prova de privação e demais condições.', ['O caput exige sempre mais15 dias? Não.', 'Exatamente15 preenche superior15? Não.'],'Privação de liberdade','Supressão da liberdade física, com modalidades e recortes distintos.')
add(149,'Condição análoga à de escravo abrange alternativas de trabalho forçado, jornada exaustiva, condições degradantes ou restrição por dívida. Não depende sempre de correntes ou impedimento físico de sair.', ['Dois a oito anos E multa, além da violência.', '§1º: transporte, vigilância/documentos com fim de reter.', '§2º: metade por criança/adolescente ou motivo discriminatório indicado.'], 'Não equiparar qualquer irregularidade trabalhista automaticamente ao tipo nem exigir restrição locomotora em todas as alternativas. Demonstrar gravidade e elementos; trabalho doméstico não é área imune ao tipo.', 'A acusação descreve condições degradantes típicas, mas o candidato exclui o crime só por não haver correntes.', 'Mera irregularidade pontual sem elementos do tipo não prova automaticamente escravidão; examinar enquadramento e provas.', ['Toda hipótese exige correntes? Não.', 'Qualquer descumprimento trabalhista basta? Não; provar elementos.'],'Alternativas típicas','Formas distintas de redução, sem requisito único de restrição física.')
add('149-a','Tráfico de pessoas reúne conduta, meio ilícito e finalidade listados; não exige sempre cruzar fronteira. Pena4 a8 e multa, aumento1/3 até metade e redução1 a2 terços na hipótese legal.', ['Finalidades: órgãos, trabalho análogo, servidão, adoção ilegal, exploração sexual.', 'Primário E não integrar organização para redução.', 'Lei13.344: publicação7/10/2016, vacância45 dias; artigos231/231-A revogados.'], 'Não criminalizar toda viagem/acolhimento sem meios e finalidade, nem ensinar transporte internacional como requisito universal. Retirada do território é majorante própria; redução exige condições cumulativas e lei no tempo.', 'Recrutamento mediante fraude para finalidade legal ocorre dentro do país: ausência de fronteira não exclui por si o tipo.', 'Viagem regular sem meio ilícito e finalidade típica não se torna tráfico apenas por transportar pessoa.', ['Exige sempre sair do Brasil? Não.', 'Primariedade sozinha basta à redução? Não; também não integrar organização.'],'Tráfico de pessoas','Conduta, meio e finalidade típicos, distinta de mero deslocamento.')
add(150,'Violação de domicílio protege entrada/permanência nas condições legais e conceito de casa, inclusive compartimento profissional não aberto ao público. Exceções devem ser integradas à Constituição e fundadas razões, não licença por suspeita vaga.', ['Caput: um a três meses OU multa; §1º: seis meses a dois anos mais violência.', '§2º revogado pela Lei13.869; não ensinar agravante histórica como vigente.', 'Quarto ocupado em habitação coletiva integra casa; área aberta não equivale a qualquer quarto.'], 'CF5ºXI e Tema280/STF: ingresso forçado sem mandado exige fundadas razões de flagrante, justificadas depois. Não usar a palavra iminência para legitimar qualquer suspeita futura ou descoberta posterior como justificativa retroativa. Consentimento e outras exceções exigem prova; não certificada toda jurisprudência de busca.', 'Há apenas suspeita genérica e o ingresso é justificado só porque depois se encontrou objeto ilícito.', 'Com fundadas razões anteriores de flagrante demonstradas, examinar hipótese e controle; mandado judicial tem requisitos próprios, inclusive período diurno.', ['Qualquer suspeita basta? Não.', 'Quarto ocupado de hospedagem perde toda proteção por estar no hotel? Não; o§4º o contempla.'],'Casa constitucionalmente protegida','Espaço de intimidade nas hipóteses legais, com exceções delimitadas.')
add(151,'Comunicações têm diferentes hipóteses de violação, divulgação e interrupção. A correspondência postal deve ser integrada ao art.40 da Lei6.538/1978; rádio/telecomunicações exigem normas posteriores, não aplicação literal universal do CP residual.', ['Caput e§1ºI possuem disciplina postal posterior correspondente.', 'Lei9.472, art.183: atividade clandestina de telecomunicações tem regime próprio.', 'Representação textual tem exceções em§1ºIV/§3º, a integrar conforme o tipo aplicável.'], 'Não ensinar pena do caput do CP como regime completo atual de toda correspondência postal nem rádio sem licença como sempre enquadrado no§1ºIV. Lei especial, finalidade e natureza do serviço importam; não certificada toda derrogação ou jurisprudência. Bloquear exercícios automáticos de literalidade residual.', 'Violação de correspondência fechada é resolvida apenas pela pena antiga do caput, ignorando art.40 da Lei6.538.', 'Se o caso é comunicação telefônica ou telecomunicação clandestina, identificar norma própria em vez de copiar a mesma resposta postal.', ['CP151 sozinho resolve todo serviço postal atual? Não.', 'Correspondência e telecomunicação têm regime necessariamente idêntico? Não; integrar normas especiais.'],'Integração das comunicações','Determinação da norma aplicável conforme objeto/serviço, sem universalizar trecho residual.')
refs={140:['https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2023/lei/l14532.htm'],141:['https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2024/lei/l14994.htm'],147:['https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2024/lei/l14994.htm'],'146-a':['https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2024/lei/l14811.htm'],'147-b':['https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2025/lei/l15123.htm'],'147-c':['https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/l15358.htm'],148:['https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/l15358.htm'],'149-a':['https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2016/lei/l13344.htm'],150:['https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm','https://noticias.stf.jus.br/postsnoticias/supremo-define-limites-para-entrada-da-policia-em-domicilio-sem-autorizacao-judicial/'],151:['https://www.planalto.gov.br/ccivil_03/leis/l6538.htm','https://www.planalto.gov.br/ccivil_03/leis/l9472.htm']}
for n,urls in refs.items():rows['art-'+str(n)]['remissoes']+=urls
import re
def readable(v):
 if isinstance(v,str):return re.sub(r'(?<=[A-Za-zÀ-ú])(?=\d)', ' ',v)
 if isinstance(v,list):return [readable(x) for x in v]
 if isinstance(v,dict):return {k:readable(x) for k,x in v.items()}
 return v
for r in rows.values():
 for k in r:
  if k!='remissoes':r[k]=readable(r[k])
if __name__=='__main__':
 assert len(rows)==20
 Path(sys.argv[1]).write_text(json.dumps(dict(course_slug='codigo-penal',units=rows),ensure_ascii=False,indent=2)+'\n');print(len(rows),'explicit honor/liberty reviews')
